import { newId, now } from '../core/ids';
import { bestGifMatch, equipmentFor, type GifCandidate } from '../core/gifMatch';
import { findSimilar } from '../core/similarity';
import type { Exercise, ExerciseKind } from '../core/types';
import { repo } from '.';
import exerciseGifs from './exerciseGifs.json';
import { mergeExercises } from './merge';
import { STARTER_CATALOG_IDS } from './seed';

/** One entry of the bundled exercise library (generated by scripts/build-exercise-catalog.mjs). */
export interface CatalogExercise {
  id: string;
  name: string;
  muscleGroup: string;
  kind: ExerciseKind;
  equipment?: string;
  /** The dataset has no photos for it. */
  noPhotos?: true;
}

/**
 * The library's photos (start and end of the movement), from free-exercise-db on GitHub through the jsDelivr CDN,
 * pinned to one commit so they can't change or vanish under us. Too many (~1,500, ~70 KB each) to ship in the app,
 * so they load when shown; the service worker keeps the ones seen. Missing or offline: the image hides itself.
 */
const PHOTOS = 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises';

export function exercisePhotos(catalogId: string): [string, string] {
  return [`${PHOTOS}/${catalogId}/0.jpg`, `${PHOTOS}/${catalogId}/1.jpg`];
}

/**
 * BETA ONLY: shows ExerciseDB's anatomical GIFs (a 3D figure, working muscles in red) instead of the photos, for
 * exercises matched to theirs by name (exerciseMedia; the library's ahead of time by scripts/match-exercise-gifs.mjs). Their free V1 GIFs
 * have no licence for apps ("All rights reserved"; ask support@ascendapi.com), so set this to false, or license
 * them, before distributing. Unmatched exercises keep their photos either way.
 */
export const USE_ANATOMICAL = true;

const GIFS = 'https://static.exercisedb.dev/media';

const nameKey = (name: string) => name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
let byName: { catalog: CatalogExercise[]; map: Map<string, CatalogExercise> } | null = null;

/**
 * The library entry whose photos to show for one of your exercises: its own link, else (for exercises made before
 * they were linked) a starter exercise's entry, or a library exercise with the same name. Only for showing photos;
 * nothing is saved.
 */
export function photoIdFor(exercise: Pick<Exercise, 'name' | 'catalogId'>, catalog: CatalogExercise[] | undefined): string | undefined {
  if (exercise.catalogId) return exercise.catalogId;
  const starter = STARTER_CATALOG_IDS.get(exercise.name.trim().toLowerCase());
  if (starter) return starter;
  if (!catalog) return undefined;
  if (byName?.catalog !== catalog) byName = { catalog, map: new Map(catalog.map((c) => [nameKey(c.name), c])) };
  const match = byName.map.get(nameKey(exercise.name));
  return match && !match.noPhotos ? match.id : undefined;
}

let gifIndex: Promise<GifCandidate[]> | null = null;

/** ExerciseDB's exercises (~70 KB), for matching names you typed yourself; only loaded while USE_ANATOMICAL is on. */
export function loadGifIndex(): Promise<GifCandidate[]> {
  gifIndex ??= import('./exerciseGifIndex.json').then((m) => m.default as GifCandidate[]);
  return gifIndex;
}

const matchedByName = new Map<string, string | undefined>();

/** What to show for an exercise: its anatomical GIF while that's on (if one matches), else its library photos. */
export interface ExerciseMedia {
  gif?: string;
  photoId?: string;
}

/**
 * The library's exercises use their ahead-of-time match (exerciseGifs.json). Ones you named yourself (no catalogId)
 * are matched by name against ExerciseDB here, once the index has loaded.
 */
export function exerciseMedia(
  exercise: Pick<Exercise, 'name' | 'catalogId' | 'kind' | 'equipment'>,
  catalog: CatalogExercise[] | undefined,
  index: GifCandidate[] | undefined,
): ExerciseMedia {
  const photoId = photoIdFor(exercise, catalog);
  if (!USE_ANATOMICAL) return { photoId };
  // While the GIFs are on, one style only: no photos (unmatched exercises get the dumbbell).
  let gifId = photoId ? (exerciseGifs as Record<string, string>)[photoId] : undefined;
  if (!gifId && !exercise.catalogId && index) {
    const key = `${exercise.name.trim().toLowerCase()}|${exercise.equipment ?? ''}|${exercise.kind}`;
    if (!matchedByName.has(key)) {
      const equipment = equipmentFor(exercise.name, exercise.equipment, exercise.kind === 'bodyweight');
      matchedByName.set(key, bestGifMatch(exercise.name, equipment, index).match?.[0]);
    }
    gifId = matchedByName.get(key);
  }
  return gifId ? { gif: `${GIFS}/${gifId}.gif` } : {};
}

