let cached: Promise<CatalogExercise[]> | null = null;

/** Loads the ~750-exercise library on first use; it ships as its own chunk and works offline. */
export function loadCatalog(): Promise<CatalogExercise[]> {
  cached ??= import('./exerciseCatalog.json').then((m) => m.default as CatalogExercise[]);
  return cached;
}

/** True when every word of the query appears in the text (so "incline db" style searches work). */
export function matchesQuery(text: string, query: string): boolean {
  const haystack = text.toLowerCase();
  return query
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .every((word) => haystack.includes(word));
}

/**
 * Adds a library exercise to the user's own list, or reuses it if it was added before
 * (restoring it if it had been removed).
 */
export async function adoptCatalogExercise(entry: CatalogExercise, existing: Exercise[]): Promise<Exercise> {
  const prior = existing.find((e) => e.catalogId === entry.id);
  if (prior) {
    if (!prior.archived) return prior;
    const restored = { ...prior, archived: false, updatedAt: now() };
    await repo.saveExercise(restored);
    return restored;
  }
  const ts = now();
  const exercise: Exercise = {
    id: newId(),
    name: entry.name,
    kind: entry.kind,
    muscleGroup: entry.muscleGroup,
    equipment: entry.equipment,
    catalogId: entry.id,
    createdAt: ts,
    updatedAt: ts,
  };
  await repo.saveExercise(exercise);
  return exercise;
}

/**
 * Turns one of your own exercises into its library version. Your history stays attached because
 * the exercise keeps its id; if the library version is already in your list, the two are merged
 * (past sessions and workout templates move over to it).
 */
export async function linkToCatalog(exercise: Exercise, entry: CatalogExercise, existing: Exercise[]): Promise<Exercise> {
  const twin = existing.find((e) => e.catalogId === entry.id && e.id !== exercise.id && !e.archived);
  if (twin) {
    await mergeExercises(twin, [exercise]);
    return twin;
  }
  const linked: Exercise = {
    ...exercise,
    name: entry.name,
    kind: entry.kind,
    muscleGroup: entry.muscleGroup,
    equipment: entry.equipment,
    catalogId: entry.id,
    archived: false,
    updatedAt: now(),
  };
  await repo.saveExercise(linked);
  return linked;
}

/** Library entries that look like `name`, leaving out ones already in your list. */
export function similarInCatalog(name: string, catalog: CatalogExercise[], existing: Exercise[]): CatalogExercise[] {
  const owned = new Set(existing.filter((e) => !e.archived && e.catalogId).map((e) => e.catalogId));
  return findSimilar(
    name,
    catalog.filter((c) => !owned.has(c.id)),
  );
}
